{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "신고 목록 조회 쿼리의 실행 계획을 해석해 인덱스 추가가 필요한 병목을 판단했는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 운영 화면의 신고 목록 조회 쿼리가 느렸던 상황",
          "task": "실행 계획에서 인덱스 추가가 필요한 이유를 판단하는 것",
          "action": "실행 계획에서 관찰한 접근 방식이나 조회 범위를 실제 조회 조건과 연결해 설명",
          "result": "관찰한 병목이 인덱스 추가 판단으로 이어진 이유 정리"
        },
        "expectedEvidence": [
          "실행 계획에서 인덱스 추가가 필요하다고 판단하게 한 구체적인 관찰",
          "해당 관찰이 신고 목록 조회 조건과 연결되는 지점",
          "인덱스가 불필요한 데이터 탐색을 줄일 수 있다고 본 이유"
        ]
      },
      "question": "포켓마켓의 신고 목록 조회 쿼리를 개선할 때, 실행 계획에서 인덱스 추가가 필요하다고 판단한 근거는 무엇이었나요?",
