      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "신고 목록 쿼리의 실행 계획에서 본 접근 방식이나 탐색 범위를 구체적으로 짚고, 조회 조건과 연결해 인덱스 추가가 필요한 이유를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "신고 목록 쿼리에 인덱스가 필요했던 이유를 전체 탐색 감소 등 일반적인 원리로 설명하지만, 당시 실행 계획에서 확인한 구체적인 근거는 제시하지 않는다."
          ]
        },
        "poor": {
          "criteria": [
            "신고 목록 쿼리에 인덱스를 추가했다는 사실이나 속도 개선 수치만 반복하고, 인덱스 추가를 판단한 근거는 제시하지 않는다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "알림 중복 발송 오류에서 로그의 구체적인 단서로 초기 추측을 수정하고 원인을 좁혔는지 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 다음 날 알림 중복 발송 문의를 받고 처음에는 클라이언트 문제로 추측했던 상황",
          "task": "로그에서 초기 추측과 다른 원인을 가리키는 단서를 찾는 것",
          "action": "시간순으로 확인한 로그 중 서버 측 중복 실행을 드러낸 기록의 특징을 설명",
          "result": "해당 단서를 통해 원인 범위를 스케줄러 중복 실행으로 좁혔다는 판단 정리"
        },
        "expectedEvidence": [
          "클라이언트 문제라는 추측을 바꾸게 한 구체적인 로그 단서",
          "그 단서를 식별한 기록의 시간 관계나 서버 구분 정보",
          "해당 기록이 클라이언트 문제가 아닌 스케줄러 중복 실행을 가리킨다고 해석한 이유"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림이 중복 발송됐을 때, 클라이언트 문제라는 추측을 바꾸게 한 로그의 단서는 무엇이었나요?",
      "answerTip": "정확한 문구가 기억나지 않으면 기억나는 특징을 설명해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "알림 중복 발송 로그의 시간 관계나 서버 구분 등 구체적인 특징을 제시하고, 그 단서가 스케줄러 중복 실행을 가리킨 이유를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "알림 중복 발송 원인을 서버 로그로 확인했다고 설명하지만, 초기 추측을 바꾼 기록의 특징은 구체적으로 제시하지 않는다."
          ]
        },
        "poor": {
          "criteria": [
            "알림 중복 발송에 잠금을 적용했다는 조치만 설명하거나, 초기 추측을 바꾸게 한 로그 단서를 제시하지 않는다."
          ]
        }
      }
    }
  ]
}

