{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "의심스러운 진통제 처방에 대해 투약을 보류한 판단의 구체적인 근거를 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자의 진통제 처방 용량이 평소 용량의 두 배로 들어온 상황",
          "task": "해당 처방대로 투약해도 되는지 판단해야 하는 상황",
          "action": "당시 확인한 정보 중 투약 보류 판단에 가장 중요했던 근거를 설명한다.",
          "result": "해당 근거가 처방을 그대로 수행하기 어렵다고 본 이유로 연결된다."
        },
        "expectedEvidence": [
          "투약을 보류해야 한다고 판단한 핵심 근거",
          "그 판단에 사용한 비교 대상이나 당시 확인한 처방 정보"
        ]
      },
      "question": "수술 후 환자의 진통제 용량이 평소의 두 배로 처방됐을 때, 투약을 보류해야 한다고 판단하는 데 가장 중요하게 본 점은 무엇이었나요?",
      "answerTip": "당시 기억나는 사실을 중심으로 본인의 생각을 차분히 설명해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "진통제 처방에 대해 단순히 '평소의 두 배였다'고 반복하는 데 그치지 않고, 비교한 처방 정보 등 투약 보류 판단의 근거를 구체적으로 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "진통제 용량이 평소와 다르면 확인해야 한다는 일반적인 원칙으로 투약 보류 판단을 설명한다."
          ]
        },
        "poor": {
          "criteria": [
            "진통제 투약을 보류한 판단의 근거를 제시하지 않거나, 담당의에게 확인한 이후의 일만 설명한다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "수술 후 환자의 활력징후 변화를 정확하게 드러내기 위해 간호기록에 남긴 관찰 정보의 구체성을 확인한다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동에서 수술 후 환자의 활력징후를 관찰하고 기록한 업무",
          "task": "환자 상태가 이전 관찰에서 어떻게 달라졌는지 간호기록에 남기는 일",
          "action": "변화의 흐름을 보여 주기 위해 실제로 기록한 관찰 정보를 설명한다.",
          "result": "설명한 기록 정보에서 환자 상태의 시간에 따른 차이가 드러난다."
        },
        "expectedEvidence": [
          "활력징후 변화의 흐름을 보여 주기 위해 기록한 구체적인 관찰 정보",
          "관찰 시점이나 이전 측정값과 달라진 정도 등 기록 정보의 세부"
        ]
      },
      "question": "정형외과 병동에서 수술 후 환자의 활력징후 변화를 기록할 때, 변화의 흐름을 보여 주는 구체적인 관찰 정보로는 무엇을 남기셨나요?",
      "answerTip": "환자 개인정보는 빼고, 직접 맡았던 업무를 중심으로 답해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "활력징후 간호기록에 남긴 정보를 관찰 시점, 이전 측정값과의 차이 등 변화의 흐름이 드러나는 구체적인 예로 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "활력징후 측정값을 정확히 기록한다는 일반적인 설명은 하지만, 변화의 흐름을 보여 주는 기록 정보는 구체화하지 못한다."
          ]
        },
        "poor": {
          "criteria": [
            "활력징후 변화에 관해 간호기록에 남긴 정보를 제시하지 않거나, 기록과 무관한 업무만 설명한다."
          ]
        }
      }
    }
  ]
}

